31	import org.springframework.samples.petclinic.rest.api.OwnersApi;
32	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
33	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
34	import org.springframework.samples.petclinic.rest.dto.PetDto;
35	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
36	import org.springframework.samples.petclinic.rest.dto.VisitDto;
37	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
38	import org.springframework.samples.petclinic.service.ClinicService;
39	import org.springframework.samples.petclinic.service.OwnerAuditPolicy;
40	import org.springframework.samples.petclinic.service.OwnerCityCapacityPolicy;
41	import org.springframework.samples.petclinic.service.OwnerCustomerCodePolicy;
42	import org.springframework.samples.petclinic.service.OwnerDailyLimitPolicy;
43	import org.springframework.samples.petclinic.service.OwnerDisposableEmailPolicy;
44	import org.springframework.samples.petclinic.service.OwnerHouseholdPolicy;
45	import org.springframework.samples.petclinic.service.OwnerNamesakePolicy;
46	import org.springframework.samples.petclinic.service.OwnerPostcodePolicy;
47	import org.springframework.samples.petclinic.service.OwnerRegistrationDatePolicy;
48	import org.springframework.security.access.prepost.PreAuthorize;
49	import org.springframework.web.bind.annotation.CrossOrigin;
50	import org.springframework.web.bind.annotation.RequestMapping;
51	import org.springframework.web.bind.annotation.RestController;
52	import org.springframework.web.util.UriComponentsBuilder;
53	
54	import jakarta.transaction.Transactional;
55	
56	/**
57	 * @author Vitaliy Fedoriv
58	 */
59	
60	@RestController
61	@CrossOrigin(exposedHeaders = "errors, content-type")
62	@RequestMapping("/api")
63	public class OwnerRestControllerV1 implements OwnersApi {
64	
65	    private final ClinicService clinicService;
66	
67	    private final OwnerMapper ownerMapper;
68	
69	    private final PetMapper petMapper;
70	
71	    private final VisitMapper visitMapper;
72	
73	    public OwnerRestControllerV1(ClinicService clinicService,
74	                                 OwnerMapper ownerMapper,
75	                                 PetMapper petMapper,
76	                                 VisitMapper visitMapper) {
77	        this.clinicService = clinicService;
78	        this.ownerMapper = ownerMapper;
79	        this.petMapper = petMapper;
80	        this.visitMapper = visitMapper;
81	    }
82	
83	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
84	    @Override
85	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
86	        Collection<Owner> owners;
87	        if (lastName != null) {
88	            owners = this.clinicService.findOwnerByLastName(lastName);
89	        } else {
90	            owners = this.clinicService.findAllOwners();
91	        }
92	        if (owners.isEmpty()) {
93	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
94	        }
95	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
96	    }
97	
98	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
99	    @Override
100	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
101	        Owner owner = this.clinicService.findOwnerById(ownerId);
102	        if (owner == null) {
103	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
104	        }
105	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
106	    }
107	
108	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
109	    @Override
110	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
111	        HttpHeaders headers = new HttpHeaders();
112	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
113	        OwnerRegistrationDatePolicy.assignBusinessDayRegistrationDate(owner);
114	        OwnerDailyLimitPolicy.rejectWhenDailyLimitReached(this.clinicService, owner);
115	        OwnerCityCapacityPolicy.rejectWhenCityAtCapacity(this.clinicService, owner);
116	        OwnerPostcodePolicy.rejectInvalidPostcode(owner);
117	        OwnerDisposableEmailPolicy.rejectDisposableDomain(owner);
118	        OwnerHouseholdPolicy.rejectDuplicateHousehold(this.clinicService, owner, ownerFieldsDto.getSharesHousehold());
119	        OwnerNamesakePolicy.assignNamesakeCount(this.clinicService, owner);
120	        OwnerCustomerCodePolicy.assignCustomerCode(this.clinicService, owner);
121	        this.clinicService.saveOwner(owner);
122	        OwnerAuditPolicy.auditCreate(owner);
123	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
124	        headers.setLocation(UriComponentsBuilder.newInstance()
125	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
126	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
127	    }
128	
129	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
130	    @Override
131	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
132	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
133	        if (currentOwner == null) {
134	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
135	        }
136	        currentOwner.setAddress(ownerFieldsDto.getAddress());
137	        currentOwner.setCity(ownerFieldsDto.getCity());
138	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
139	        currentOwner.setLastName(ownerFieldsDto.getLastName());
140	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
141	        this.clinicService.saveOwner(currentOwner);
142	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
143	    }
144	
145	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
146	    @Transactional
147	    @Override
148	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
149	        Owner owner = this.clinicService.findOwnerById(ownerId);
150	        if (owner == null) {
151	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
152	        }
153	        this.clinicService.deleteOwner(owner);
154	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
155	    }
156	
157	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
158	    @Override
159	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
160	        Owner owner = this.clinicService.findOwnerById(ownerId);
161	        if (owner == null) {
162	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
163	        }
164	        HttpHeaders headers = new HttpHeaders();
165	        Pet pet = petMapper.toPet(petFieldsDto);
166	        owner.setId(ownerId);
167	        pet.setOwner(owner);
168	        pet.getType().setName(null);
169	        this.clinicService.savePet(pet);
170	        PetDto petDto = petMapper.toPetDto(pet);
171	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
172	            .buildAndExpand(pet.getId()).toUri());
173	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
174	    }
175	
176	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
177	    @Override
178	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
179	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
180	        if (currentOwner != null) {
181	            Pet currentPet = this.clinicService.findPetById(petId);
182	            if (currentPet != null) {
183	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
184	                currentPet.setName(petFieldsDto.getName());
185	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
186	                this.clinicService.savePet(currentPet);
187	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
188	            }
189	        }
190	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
191	    }
192	
193	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
194	    @Override
195	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
196	        HttpHeaders headers = new HttpHeaders();
197	        Visit visit = visitMapper.toVisit(visitFieldsDto);
198	        Pet pet = new Pet();
199	        pet.setId(petId);
200	        visit.setPet(pet);
201	        this.clinicService.saveVisit(visit);
202	        VisitDto visitDto = visitMapper.toVisitDto(visit);
203	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
204	            .buildAndExpand(visit.getId()).toUri());
205	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
206	    }
207	
208	
209	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
210	    @Override
211	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
212	        Owner owner = this.clinicService.findOwnerById(ownerId);
213	        if (owner != null) {
214	            Pet pet = owner.getPet(petId);
215	            if (pet != null) {
216	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
217	            }
218	        }
219	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
220	    }
221	}
