27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be E.164, e.g. +61412345678")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "registration_date")
55	    private LocalDate registrationDate;
56	
57	    @Column(name = "customer_code")
58	    private String customerCode;
59	
60	    @Column(name = "household_id")
61	    private String householdId;
62	
63	    @Column(name = "namesake_count")
64	    private Integer namesakeCount;
65	
66	    @Column(name = "postcode")
67	    private String postcode;
68	
69	    @Column(name = "possible_duplicate_of")
70	    private Integer possibleDuplicateOf;
71	
72	    public Integer getPossibleDuplicateOf() {
73	        return this.possibleDuplicateOf;
74	    }
75	
76	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
77	        this.possibleDuplicateOf = possibleDuplicateOf;
78	    }
79	
80	    /** True when this owner soft-matched an existing owner (see {@code possibleDuplicateOf}). */
81	    public Boolean getPossibleDuplicate() {
82	        return this.possibleDuplicateOf != null;
83	    }
84	
85	    @Column(name = "birth_date")
86	    private LocalDate birthDate;
87	
88	    public LocalDate getBirthDate() {
89	        return this.birthDate;
90	    }
91	
92	    public void setBirthDate(LocalDate birthDate) {
93	        this.birthDate = birthDate;
94	    }
95	
96	    public String getPostcode() {
97	        return this.postcode;
98	    }
99	
100	    public void setPostcode(String postcode) {
101	        this.postcode = postcode;
102	    }
103	
104	    public Integer getNamesakeCount() {
105	        return this.namesakeCount;
106	    }
107	
108	    public void setNamesakeCount(Integer namesakeCount) {
109	        this.namesakeCount = namesakeCount;
110	    }
111	
112	    public String getCustomerCode() {
113	        return this.customerCode;
114	    }
115	
116	    public void setCustomerCode(String customerCode) {
117	        this.customerCode = customerCode;
118	    }
119	
120	    public String getHouseholdId() {
121	        return this.householdId;
122	    }
123	
124	    public void setHouseholdId(String householdId) {
125	        this.householdId = householdId;
126	    }
127	
128	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
129	    private Set<Pet> pets;
130	
131	    public LocalDate getRegistrationDate() {
132	        return this.registrationDate;
133	    }
134	
135	    public void setRegistrationDate(LocalDate registrationDate) {
136	        this.registrationDate = registrationDate;
137	    }
138	
139	    /** Default the registration date to the server's current date when none was supplied. */
140	    @PrePersist
141	    void defaultRegistrationDate() {
142	        if (this.registrationDate == null) {
143	            this.registrationDate = LocalDate.now();
144	        }
145	    }
146	
147	    public String getEmail() {
148	        return this.email;
149	    }
150	
151	    public void setEmail(String email) {
152	        this.email = email;
153	    }
154	
155	    public String getAddress() {
156	        return this.address;
157	    }
158	
159	    public void setAddress(String address) {
160	        this.address = address;
161	    }
162	
163	    public String getCity() {
164	        return this.city;
165	    }
166	
167	    public void setCity(String city) {
168	        this.city = city;
169	    }
170	
171	    public String getTelephone() {
172	        return this.telephone;
173	    }
174	
175	    public void setTelephone(String telephone) {
176	        this.telephone = telephone;
177	    }
178	
179	    protected Set<Pet> getPetsInternal() {
180	        if (this.pets == null) {
181	            this.pets = new HashSet<>();
182	        }
183	        return this.pets;
184	    }
185	
186	    protected void setPetsInternal(Set<Pet> pets) {
187	        this.pets = pets;
188	    }
189	
190	    public List<Pet> getPets() {
191	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
192	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
193	        return Collections.unmodifiableList(sortedPets);
194	    }
195	
196	    public void setPets(List<Pet> pets) {
197	        this.pets = new HashSet<>(pets);
198	    }
199	
200	    public void addPet(Pet pet) {
201	        getPetsInternal().add(pet);
202	        pet.setOwner(this);
203	    }
204	
205	    /**
206	     * Return the Pet with the given name, or null if none found for this Owner.
207	     *
208	     * @param name to test
209	     * @return true if pet name is already in use
210	     */
211	    public Pet getPet(String name) {
212	        return getPet(name, false);
213	    }
214	
215	    /**
216	     * Return the Pet with the given name, or null if none found for this Owner.
217	     *
218	     * @param name to test
219	     * @return true if pet name is already in use
220	     */
221	    public Pet getPet(String name, boolean ignoreNew) {
222	        name = name.toLowerCase();
223	        for (Pet pet : getPetsInternal()) {
224	            if (!ignoreNew || !pet.isNew()) {
225	                String compName = pet.getName();
226	                compName = compName.toLowerCase();
227	                if (compName.equals(name)) {
228	                    return pet;
229	                }
230	            }
231	        }
232	        return null;
233	    }
234	
235	    public Pet getPet(Integer petId) {
236	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
237	    }
238	
239	    @Override
240	    public String toString() {
241	        return new ToStringCreator(this)
242	
243	            .append("id", this.getId())
244	            .append("new", this.isNew())
245	            .append("lastName", this.getLastName())
246	            .append("firstName", this.getFirstName())
247	            .append("address", this.address)
248	            .append("city", this.city)
249	            .append("telephone", this.telephone)
250	            .toString();
251	    }
252	}
