10	/**
11	 * Business rule: an owner's effective registration date must fall on a business day. The effective
12	 * date is the one supplied on the request, or the server's current date when none was supplied; a
13	 * Saturday or Sunday rolls forward to the following Monday. Kept as a small, self-contained unit so
14	 * the rule can be applied from the create flow before any value derived from the registration date
15	 * (membership number, per-day create limit) is computed.
16	 */
17	public final class OwnerRegistrationDatePolicy {
18	
19	    private OwnerRegistrationDatePolicy() {
20	    }
21	
22	    /** Set the owner's registrationDate to its effective business-day value. */
23	    public static void assignBusinessDayRegistrationDate(Owner owner) {
24	        LocalDate supplied = owner.getRegistrationDate();
25	        rejectFutureDate(supplied);
26	        LocalDate effective = supplied != null ? supplied : LocalDate.now();
27	        owner.setRegistrationDate(rollToBusinessDay(effective));
28	    }
29	
30	    /** Reject a supplied registration date that is later than the server's current date. */
31	    private static void rejectFutureDate(LocalDate supplied) {
32	        if (supplied != null && supplied.isAfter(LocalDate.now())) {
33	            throw new FutureRegistrationDateException();
34	        }
35	    }
36	
37	    private static LocalDate rollToBusinessDay(LocalDate date) {
38	        if (date.getDayOfWeek() == DayOfWeek.SATURDAY) {
39	            return date.plusDays(2);
40	        }
41	        if (date.getDayOfWeek() == DayOfWeek.SUNDAY) {
42	            return date.plusDays(1);
43	        }
44	        return date;
45	    }
46	
47	    /** Thrown when a supplied registration date is later than the server's current date. */
48	    @ResponseStatus(HttpStatus.BAD_REQUEST)
49	    public static class FutureRegistrationDateException extends RuntimeException {
50	    }
51	}
