1	package org.springframework.samples.petclinic.service;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	import org.springframework.http.HttpStatus;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.web.bind.annotation.ResponseStatus;
10	
11	/**
12	 * Business rule: a household is keyed on (last name, postcode). Every owner is given a
13	 * deterministic {@code householdId} on creation &mdash; the first 12 hex characters of
14	 * SHA-256 over {@code normalizedLastName|postcode} &mdash; so owners with the same last name
15	 * and postcode share it automatically. Because they are the same household, a second such owner
16	 * is rejected unless the request opts in to sharing ({@code sharesHousehold == true}), which only
17	 * bypasses the rejection; the id is assigned either way. Kept as a small, self-contained unit so
18	 * the rule can be enforced from the create flow without adding complexity to the controller or
19	 * service.
20	 */
21	public final class OwnerHouseholdPolicy {
22	
23	    private OwnerHouseholdPolicy() {
24	    }
25	
26	    /**
27	     * Assign the owner's deterministic {@code householdId} and reject it when another existing owner
28	     * is in the same (last name, postcode) household, unless the request opted in to sharing.
29	     *
30	     * @param clinicService   source of the existing owners
31	     * @param owner           the owner being created
32	     * @param sharesHousehold whether the request opted in to a shared household
33	     * @throws DuplicateHouseholdException if the household already exists and sharing was not opted in
34	     */
35	    public static void rejectDuplicateHousehold(ClinicService clinicService, Owner owner, Boolean sharesHousehold) {
36	        String lastName = normalize(owner.getLastName());
37	        String postcode = orEmpty(owner.getPostcode());
38	        owner.setHouseholdId(householdId(lastName, postcode));
39	        for (Owner existing : clinicService.findAllOwners()) {
40	            if (!existing.getId().equals(owner.getId())
41	                && lastName.equals(normalize(existing.getLastName()))
42	                && postcode.equals(orEmpty(existing.getPostcode()))) {
43	                if (!Boolean.TRUE.equals(sharesHousehold)) {
44	                    throw new DuplicateHouseholdException();
45	                }
46	                return;
47	            }
48	        }
49	    }
50	
51	    private static String normalize(String value) {
52	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase();
53	    }
54	
55	    private static String orEmpty(String value) {
56	        return value == null ? "" : value;
57	    }
58	
59	    /** Derive a stable identifier shared by every owner in the same (last name, postcode) household. */
60	    private static String householdId(String lastName, String postcode) {
61	        try {
62	            byte[] digest = MessageDigest.getInstance("SHA-256")
63	                .digest((lastName + "|" + postcode).getBytes(StandardCharsets.UTF_8));
64	            StringBuilder sb = new StringBuilder();
65	            for (int i = 0; i < 6; i++) {
66	                sb.append(String.format("%02x", digest[i]));
67	            }
68	            return sb.toString();
69	        }
70	        catch (NoSuchAlgorithmException e) {
71	            throw new IllegalStateException(e);
72	        }
73	    }
74	
75	    /** Thrown when another owner already shares the same last name and postcode. */
76	    @ResponseStatus(HttpStatus.CONFLICT)
77	    public static class DuplicateHouseholdException extends RuntimeException {
78	    }
79	}
