3	import org.springframework.samples.petclinic.model.Owner;
4	
5	/**
6	 * Business rule: on creation an owner records its {@code namesakeCount}, the number of existing
7	 * owners that already share the same first and last name (compared case-insensitively) at the
8	 * moment before this owner is created. Kept as a small, self-contained unit so the rule can be
9	 * applied from the create flow without adding complexity to the controller or service.
10	 */
11	public final class OwnerNamesakePolicy {
12	
13	    private OwnerNamesakePolicy() {
14	    }
15	
16	    /**
17	     * Record the {@code namesakeCount} for a newly created owner.
18	     *
19	     * @param clinicService source of the existing owners
20	     * @param owner         the owner being created
21	     */
22	    public static void assignNamesakeCount(ClinicService clinicService, Owner owner) {
23	        String firstName = owner.getFirstName();
24	        String lastName = owner.getLastName();
25	        int count = 0;
26	        for (Owner existing : clinicService.findAllOwners()) {
27	            if (firstName.equalsIgnoreCase(existing.getFirstName())
28	                && lastName.equalsIgnoreCase(existing.getLastName())) {
29	                count++;
30	            }
31	        }
32	        owner.setNamesakeCount(count);
33	    }
34	}
