1	package org.springframework.samples.petclinic.service;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.Map;
7	
8	import org.springframework.samples.petclinic.model.Owner;
9	
10	/**
11	 * Business rule: on creation an owner is assigned a {@code customerCode} formatted
12	 * {@code <REGION>-<HASH8>}, where REGION is the region code derived from the owner's postcode
13	 * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099, else {@code UNKNOWN}) and HASH8 is the first
14	 * eight upper-case hex characters of SHA-256 over the normalized telephone concatenated with
15	 * the last name (e.g. {@code NSW-1A2B3C4D}). Kept as a small, self-contained unit so the rule
16	 * can be applied from the create flow without adding complexity to the controller or service.
17	 */
18	public final class OwnerCustomerCodePolicy {
19	
20	    private static final Map<String, int[]> REGION_RANGE = Map.of(
21	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
22	
23	    private OwnerCustomerCodePolicy() {
24	    }
25	
26	    /**
27	     * Assign the {@code customerCode} for a newly created owner.
28	     *
29	     * @param clinicService retained for call-site compatibility; not used by the identity rule
30	     * @param owner         the owner being created
31	     */
32	    public static void assignCustomerCode(ClinicService clinicService, Owner owner) {
33	        owner.setCustomerCode(region(owner.getPostcode()) + "-" + hash8(owner));
34	    }
35	
36	    /** The region whose postcode range contains {@code postcode}, or {@code UNKNOWN}. */
37	    static String region(String postcode) {
38	        if (postcode != null) {
39	            int code = Integer.parseInt(postcode);
40	            for (Map.Entry<String, int[]> entry : REGION_RANGE.entrySet()) {
41	                int[] range = entry.getValue();
42	                if (code >= range[0] && code <= range[1]) {
43	                    return entry.getKey();
44	                }
45	            }
46	        }
47	        return "UNKNOWN";
48	    }
49	
50	    /** First eight upper-case hex characters of SHA-256(normalizedTelephone + lastName). */
51	    private static String hash8(Owner owner) {
52	        String input = orEmpty(owner.getTelephone()) + orEmpty(owner.getLastName());
53	        try {
54	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(input.getBytes(StandardCharsets.UTF_8));
55	            StringBuilder sb = new StringBuilder();
56	            for (int i = 0; i < 4; i++) {
57	                sb.append(String.format("%02X", digest[i]));
58	            }
59	            return sb.toString();
60	        }
61	        catch (NoSuchAlgorithmException e) {
62	            throw new IllegalStateException(e);
63	        }
64	    }
65	
66	    private static String orEmpty(String value) {
67	        return value == null ? "" : value;
68	    }
69	}
